reproducer.generation_driver_rust:
use toucan_bindings::{generate, Options};
use toucan_semantic::analyze;
use toucan_target::Target;
fn main() {
    for (name, source) in [
        ("struct_const", "typedef const unsigned T; struct S { T bits:3; };"),
        ("struct_volatile", "typedef volatile unsigned T; struct S { T bits:3; };"),
        ("union_const", "typedef const unsigned T; union U { T bits:3; unsigned value; };"),
        ("union_volatile", "typedef volatile unsigned T; union U { T bits:3; unsigned value; };"),
        ("union_partial", "union U { unsigned bit:1; unsigned bytes[4]; };"),
        ("struct_padding", "struct S { unsigned a:1; unsigned :23; unsigned b:1; };"),
    ] {
        let unit = analyze(source, Target::X86_64UnknownLinuxGnu).unwrap();
        std::fs::write(format!("{name}.h"), source).unwrap();
        match generate(&unit, &Options::default()) {
            Ok(bindings) => { std::fs::write(format!("{name}.rs"), bindings.source).unwrap(); println!("{name}: generated"); },
            Err(error) => println!("{name}: {error}"),
        }
    }
}

