#![allow(dead_code, non_camel_case_types)]
mod union { include!("../../union_partial.rs"); }
mod structure { include!("../../struct_padding.rs"); }
#[repr(C, packed)] struct Packed { lead: u8, value: union::U }
fn main() {
    unsafe {
        let mut raw = core::mem::MaybeUninit::<union::U>::uninit();
        raw.as_mut_ptr().cast::<u8>().write(0);
        let mut partial = raw.assume_init();
        partial.set_bit(1);
        assert_eq!(partial.bit(), 1);
        let mut packed = Packed { lead: 0, value: partial };
        let ptr = core::ptr::addr_of_mut!(packed.value);
        let mut local = ptr.read_unaligned();
        local.set_bit(0);
        ptr.write_unaligned(local);
        assert_eq!(ptr.read_unaligned().bit(), 0);
        let mut raw = core::mem::MaybeUninit::<structure::S>::uninit();
        let bytes=raw.as_mut_ptr().cast::<u8>();
        bytes.write(1); bytes.add(3).write(1);
        let mut sparse=raw.assume_init();
        assert_eq!(sparse.a(),1);assert_eq!(sparse.b(),1);
        sparse.set_a(0); sparse.set_b(0);
        assert_eq!(sparse.a(),0);assert_eq!(sparse.b(),0);
        if std::env::args().any(|a| a == "negative") {
            let invalid=core::mem::MaybeUninit::<union::U>::uninit().assume_init();
            // Deliberate violation: test that Miri catches the documented
            // requirement to initialize all bytes touched by the bitfield.
            let _=invalid.bit();
        }
    }
}
